472		if err != nil {
473			t.Fatal(err)
474		}
475	
476		for _, tc := range []struct {
477			name   string
478			before string
479			after  string
480			named  string
481		}{
482			{"second report corrupt", goodID, badID, badID},
483			{"first report corrupt", badID, goodID, badID},
484		} {
485			t.Run(tc.name, func(t *testing.T) {
486				if data, _ := os.ReadFile(filepath.Join(dir, badID+".json")); !bytes.Contains(data, []byte(`"note":null`)) {
487					t.Fatalf("subtest start: archive already repaired:\n%s", data)
488				}
489				diff, err := DiffStore(dir, tc.before, tc.after)
490				if data, _ := os.ReadFile(filepath.Join(dir, badID+".json")); !bytes.Contains(data, []byte(`"note":null`)) {
491					t.Fatalf("subtest end: DiffStore rewrote the archive:\n%s", data)
492				}
493				if err == nil {
494					t.Fatalf("diff must fail when a side carries a non-string rule text member, got %+v", diff)
495				}
496				var ec errCorrupt
497				if !errors.As(err, &ec) {
498					t.Fatalf("expected errCorrupt, got %T: %v", err, err)
499				}
500				if !strings.Contains(err.Error(), "r-extra") ||
501					!strings.Contains(err.Error(), "note must be a string") ||
502					!strings.Contains(err.Error(), "rules[3]") ||
503					!strings.Contains(err.Error(), tc.named) {
504					t.Fatalf("error must name the report, position, rule and string requirement: %v", err)
505				}
506				if !reflect.DeepEqual(diff, DiffResult{}) {
507					t.Fatalf("failed diff must return the zero result, got %+v", diff)
508				}
509			})
510		}
511	
512		// 失败的比较不得修复、覆盖损坏侧归档：重复失败后损坏字节原样保留。
513		for i := 0; i < 2; i++ {
514			if _, err := DiffStore(dir, goodID, badID); err == nil {
515				t.Fatal("diff against the corrupt side must keep failing")
516			}
517			kept, err := os.ReadFile(filepath.Join(dir, badID+".json"))
518			if err != nil {
519				t.Fatal(err)
520			}
521			if !bytes.Contains(kept, []byte(`"note":null`)) {
522				t.Fatalf("failed diff must leave the corrupt archive untouched:\n%s", kept)
523			}
524		}
525	
526		// 恢复另一侧后比较成功：证明失败只来自类型关，且成功的比较同样不重写
527		// 归档，既有合法报告的比较分类与统计保持不变。
528		if err := os.WriteFile(filepath.Join(dir, otherID+".json"), cleanOther, 0o644); err != nil {
529			t.Fatal(err)
530		}
531		diff, err := DiffStore(dir, goodID, otherID)
532		if err != nil {
533			t.Fatalf("restored archive must diff successfully: %v", err)
534		}
535		if diff.Summary.AddedRules != 1 || diff.Summary.NoChange != 3 {
536			t.Fatalf("legal comparison categories must be unchanged: %+v", diff.Summary)
537		}
538		afterRestore, err := os.ReadFile(filepath.Join(dir, otherID+".json"))
539		if err != nil {
540			t.Fatal(err)
541		}
542		if !bytes.Equal(afterRestore, cleanOther) {
543			t.Fatal("successful diff must not rewrite the archive")
544		}
545		if bytes.Equal(badBytes, cleanOther) {
546			t.Fatal("test setup: the mutated archive must differ from the clean one")
547		}
548	}
