301		} {
302			t.Run(tc.name, func(t *testing.T) {
303				check := fmt.Sprintf(
304					`{"artifactHash":%q,"ruleId":"r1","version":"1.0.0",%s,"note":"ce"}`,
305					hash, tc.patch)
306				in := strictDoc(
307					`"artifact":`+strictArtifactJSON,
308					`"rules":`+strictRulesJSON,
309					`"checks":[`+check+`]`,
310				)
311				_, _, _, _, err := ParseAuditInput([]byte(in))
312				if err == nil {
313					t.Fatal("an unsupported formal status must reject")
314				}
315				if !strings.Contains(err.Error(), "r1") {
316					t.Fatalf("error must identify rule r1: %v", err)
317				}
318				if !strings.Contains(err.Error(), "unknown status bogus") {
319					t.Fatalf("error must name the unsupported formal status: %v", err)
320				}
321			})
322		}
323	}
324	
325	// --- 正式 status 类型不是字符串：不能被扩展成员掩盖 ---
326	
327	func TestParseAuditNonStringFormalStatusRejected(t *testing.T) {
328		hash := ArtifactHash(strictTestArtifact())
329		check := fmt.Sprintf(
330			`{"artifactHash":%q,"ruleId":"r1","version":"1.0.0","StAtus":"通过","status":123}`,
331			hash)
332		in := strictDoc(
333			`"artifact":`+strictArtifactJSON,
334			`"rules":`+strictRulesJSON,
335			`"checks":[`+check+`]`,
336		)
337		_, _, _, _, err := ParseAuditInput([]byte(in))
338		if err == nil {
339			t.Fatal("a non-string formal status must reject")
340		}
341		if !strings.Contains(err.Error(), "r1") || !strings.Contains(err.Error(), "string") {
342			t.Fatalf("error must name the rule and require a string status: %v", err)
343		}
344	}
345	
346	// --- 没有 ruleId 的记录，正式 status 缺失时仍被拒绝（不会 panic，位置可辨） ---
347	
348	func TestParseAuditBadStatusWithoutRuleIDRejected(t *testing.T) {
349		hash := ArtifactHash(strictTestArtifact())
350		check := fmt.Sprintf(`{"artifactHash":%q,"version":"1.0.0","StAtus":"通过"}`, hash)
351		in := strictDoc(
352			`"artifact":`+strictArtifactJSON,
353			`"rules":`+strictRulesJSON,
354			`"checks":[`+check+`]`,
355		)
356		_, _, _, _, err := ParseAuditInput([]byte(in))
357		if err == nil || !strings.Contains(err.Error(), "status") {
358			t.Fatalf("missing formal status must reject even without a ruleId: %v", err)
359		}
360	}
361	
362	// --- 不变式名称大小写敏感、空格不修剪；值仍只接受布尔 ---
363	
364	func TestParseAuditInvariantNamesAreUserDefined(t *testing.T) {
365		in := strictDoc(
366			`"artifact":`+strictArtifactJSON,
367			`"rules":`+strictRulesJSON,
368			`"invariants":{"Inv":true,"inv":false," inv ":true}`,
369		)
370		_, _, invariants, _, err := ParseAuditInput([]byte(in))
371		if err != nil {
372			t.Fatalf("Inv, inv and \" inv \" are three distinct invariants: %v", err)
373		}
374		if len(invariants) != 3 {
375			t.Fatalf("want 3 distinct invariant names, got %+v", invariants)
376		}
377		if invariants["Inv"] != true || invariants["inv"] != false || invariants[" inv "] != true {
378			t.Fatalf("invariant names/values not preserved exactly: %+v", invariants)
379		}
380	
381		// 规则引用小写 inv：取 false，产生缺陷，与 Inv / " inv " 无关。
382		got := strictParsedReport(t, in)
383		if len(got.Findings) != 1 || got.Findings[0].Invariant != "inv" {
384			t.Fatalf("rule must bind to lowercase inv=false: %+v", got.Findings)
385		}
386	
387		// 用户定义名称下，非布尔值依旧整体拒绝。
388		bad := strictDoc(
389			`"artifact":`+strictArtifactJSON,
390			`"rules":`+strictRulesJSON,
391			`"invariants":{"Inv":"true","inv":false}`,
392		)
393		_, _, _, _, err = ParseAuditInput([]byte(bad))
394		if err == nil || !strings.Contains(err.Error(), "Inv") || !strings.Contains(err.Error(), "boolean") {
395			t.Fatalf("non-boolean invariant Inv must reject and be named: %v", err)
396		}
397	}
398	
399	// --- 扩展对象内部重复成员仍整份拒绝，不能因为忽略扩展信息而放行 ---
400	
401	func TestParseAuditDuplicateMemberInsideExtensionRejected(t *testing.T) {
402		hash := ArtifactHash(strictTestArtifact())
403		check := fmt.Sprintf(
404			`{"artifactHash":%q,"ruleId":"r1","version":"1.0.0","status":"通过","ext":{"a":1,"a":2}}`,
405			hash)
406		in := strictDoc(
407			`"artifact":`+strictArtifactJSON,
408			`"rules":`+strictRulesJSON,
409			`"checks":[`+check+`]`,
410		)
411		_, _, _, _, err := ParseAuditInput([]byte(in))
412		if err == nil {
413			t.Fatal("a duplicate member inside an extension object must still reject the submission")
414		}
415		if !strings.Contains(strings.ToLower(err.Error()), "duplicate") {
416			t.Fatalf("error must classify the problem as a duplicate member: %v", err)
417		}
418	
419		// 顶层扩展对象重复成员同样拒绝。
420		topExt := strictDoc(
421			`"artifact":`+strictArtifactJSON,
422			`"rules":`+strictRulesJSON,
423			`"mystery":{"x":1,"x":2}`,
424		)
425		if _, _, _, _, err := ParseAuditInput([]byte(topExt)); err == nil {
426			t.Fatal("a duplicate member inside a top-level extension object must reject")
427		}
428	}
429	
430	// --- 仅出现一次的未知成员继续放行，不因未知名称本身被拒绝 ---
431	
432	func TestParseAuditSingleUnknownMemberAccepted(t *testing.T) {
433		hash := ArtifactHash(strictTestArtifact())
434		check := fmt.Sprintf(
435			`{"artifactHash":%q,"ruleId":"r1","version":"1.0.0","status":"通过","mystery":{"nested":[true,null]}}`,
436			hash)
437		in := strictDoc(
438			`"artifact":`+strictArtifactJSON,
439			`"rules":`+strictRulesJSON,
440			`"checks":[`+check+`]`,
441			`"extraTop":"hello"`,
442		)
443		got := strictParsedReport(t, in)
444		if got.Rules[0].Status != StatusPass || len(got.Findings) != 0 {
445			t.Fatalf("unknown extension members must be allowed and ignored: %+v", got)
446		}
