22	// jsonString quotes a Go string as a JSON string literal, so tests can embed
23	// text containing newlines, tabs and CJK characters without hand-escaping.
24	func jsonString(s string) string {
25		b, err := json.Marshal(s)
26		if err != nil {
27			panic(err)
28		}
29		return string(b)
30	}
