56	func TestParseAuditNullSourceWithEmptyRulesRejected(t *testing.T) {
57		in := artifactFieldsDoc(`"name":"Vault"`, `"abi":"","bytecode":"","source":null`, "")
58		artifact, rules, invariants, checks, err := ParseAuditInput([]byte(in))
59		if err == nil {
