92					!strings.Contains(err.Error(), "artifact."+tc.field) ||
93					!strings.Contains(err.Error(), "must be a string") {
94					t.Fatalf("null %s must reject and name artifact.%s: %v", tc.field, tc.field, err)
95				}
96				// 有规则（且规则并不引用该字段）时同样拒绝。
97				withRule := strings.Replace(tc.doc, `"rules":[]`, `"rules":[`+artifactTextRule+`]`, 1)
98				if _, _, _, _, err := ParseAuditInput([]byte(withRule)); err == nil ||
99					!strings.Contains(err.Error(), "artifact."+tc.field+" must be a string") {
100					t.Fatalf("null %s must reject even with an unrelated rule present: %v", tc.field, err)
101				}
102			})
103		}
104	}
