183		}
184		if _, err := BuildReport(a, rules, inv, checks); err == nil ||
185			!strings.Contains(err.Error(), "requires an ABI") {
186			t.Fatalf("an empty ABI must still fail the ABI business rule: %v", err)
187		}
188	
189		// 符号规则 + 显式空字节码：仍是既有字节码业务错误。
190		emptyBytecode := artifactFieldsDoc(`"name":"Vault"`, `"abi":"a","bytecode":"","source":"s"`,
191			`{"id":"r-sym","kind":"symbolic","severity":"high","invariant":"inv","version":"1.0.0"}`)
192		a, rules, inv, checks, err = ParseAuditInput([]byte(emptyBytecode))
193		if err != nil {
194			t.Fatalf("an explicit empty bytecode is a legal string and must parse: %v", err)
195		}
196		if _, err := BuildReport(a, rules, inv, checks); err == nil ||
197			!strings.Contains(err.Error(), "requires bytecode") {
198			t.Fatalf("empty bytecode must still fail the symbolic business rule: %v", err)
