202	// --- 类型错误是提交格式错误：不能记成缺陷、工具缺失或超时 ---
203	
204	func TestParseAuditNonStringArtifactFieldIsNotAConclusion(t *testing.T) {
205		// 即使存在规则，产物字段类型错误也在构建报告之前拒绝，永远不会以任何
206		// 检查结论落盘。
207		in := artifactFieldsDoc(`"name":"Vault"`, `"abi":"","bytecode":"","source":null`, artifactTextRule)
