220	
221	func TestParseAuditArtifactVariantNamesIgnored(t *testing.T) {
222		// 正式成员省略，变体携带字符串：只是扩展信息，字段仍取默认空值。
223		variantSupplies := `{"artifact":{"name":"Vault","Source":"file.sol"," ABI ":"a"},"rules":[]}`
224		got := strictParsedReport(t, variantSupplies)
225		plain := strictParsedReport(t, `{"artifact":{"name":"Vault"},"rules":[]}`)
226		if got.ReportID != plain.ReportID {
227			t.Fatalf("a variant-named member must not supply a formal field:\n got %s\nwant %s",
228				got.ReportID, plain.ReportID)
229		}
230	
231		// 变体携带 null：只是扩展信息，不触发类型错误。
232		variantNull := `{"artifact":{"name":"Vault","Source":null," ABI ":null},"rules":[]}`
233		if _, _, _, _, err := ParseAuditInput([]byte(variantNull)); err != nil {
234			t.Fatalf("null under a variant name is extension data and must be ignored: %v", err)
235		}
236	
237		// 正式 source 为 null，变体携带合法字符串（位于其前或其后）都不能挽救。
238		for _, pos := range []string{"before", "after"} {
239			t.Run(pos, func(t *testing.T) {
240				var artifact string
241				if pos == "before" {
242					artifact = `{"Source":"file.sol","source":null}`
243				} else {
244					artifact = `{"source":null,"Source":"file.sol"}`
245				}
246				in := `{"artifact":` + artifact + `,"rules":[]}`
247				_, _, _, _, err := ParseAuditInput([]byte(in))
248				if err == nil || !strings.Contains(err.Error(), "artifact.source must be a string") {
249					t.Fatalf("a variant member must not rescue a null formal source: %v", err)
250				}
251			})
252		}
253	
254		// 带首尾空格的名称同样不能挽救。
255		padded := `{"artifact":{"name":"Vault"," source ":"x","source":null},"rules":[]}`
256		if _, _, _, _, err := ParseAuditInput([]byte(padded)); err == nil ||
257			!strings.Contains(err.Error(), "artifact.source must be a string") {
258			t.Fatalf("a whitespace-padded variant must not rescue the formal null: %v", err)
259		}
260	}
261	
262	// --- Unicode 转义写出的正式名称遵守同一字符串规则 ---
263	
264	func TestParseAuditEscapedArtifactNameFollowsSameRule(t *testing.T) {
265		// 字段名 "source" 用 Unicode 转义写出（s 的码位是 0x73）。转义在运行期
266		// 拼接，使提交给解析器的字节确实携带 JSON 转义写法，解码后名称等于
267		// source：null 同样整份拒绝。
268		escName := "\\" + "u0073" + "ource"
269		plainNull := artifactFieldsDoc(`"name":"Vault"`, `"abi":"","bytecode":"","source":null`, "")
270		escapedNull := strings.Replace(plainNull, `"source":null`, `"`+escName+`":null`, 1)
271		if !strings.Contains(escapedNull, `\`+"u0073ource") {
272			t.Fatalf("test setup must carry the JSON escape, got %s", escapedNull)
273		}
274		if _, _, _, _, err := ParseAuditInput([]byte(escapedNull)); err == nil ||
275			!strings.Contains(err.Error(), "artifact.source must be a string") {
276			t.Fatalf("an escaped formal name with null must reject like the plain spelling: %v", err)
277		}
278	
279		// 转义写法携带合法字符串时，与直接书写的产物哈希与报告标识一致。
280		plainLegal := artifactFieldsDoc(`"name":"Vault"`, `"abi":"a","bytecode":"b","source":"s"`, artifactTextRule)
281		escaped := strings.Replace(plainLegal, `"source":"s"`, `"`+escName+`":"s"`, 1)
282		rEscaped := strictParsedReport(t, escaped)
283		rPlain := strictParsedReport(t, plainLegal)
284		if rEscaped.ReportID != rPlain.ReportID || rEscaped.Artifact.Hash != rPlain.Artifact.Hash {
285			t.Fatalf("escaped and plain spellings must share report id and hash:\n%s\n%s",
286				rEscaped.ReportID, rPlain.ReportID)
287		}
288	}
289	
290	// --- 合法字符串逐字保留：中文、换行与前后空格，source 是文本而非文件名 ---
291	
292	func TestParseAuditLegalArtifactStringsPreserved(t *testing.T) {
293		// source 即便长得像文件名，也只作为提交文本参与哈希，绝不按文件读取。
294		source := "  contract 金库 {\n // 中文注释 \n}\t"
295		abi := " [ { \"name\" : \"取款\" } ] "
296		bytecode := "  0x6080\n6040  "
297		in := artifactFieldsDoc(`"name":" 金库 Vault "`,
298			`"abi":`+jsonString(abi)+`,"bytecode":`+jsonString(bytecode)+`,"source":`+jsonString(source),
299			"")
300		artifact, _, _, _, err := ParseAuditInput([]byte(in))
301		if err != nil {
302			t.Fatalf("a legal submission with multilingual/whitespace text must parse: %v", err)
303		}
304		if artifact.Name != " 金库 Vault " || artifact.ABI != abi ||
305			artifact.Bytecode != bytecode || artifact.Source != source {
306			t.Fatalf("artifact text must be preserved verbatim:\n%+v", artifact)
307		}
308	
309		// 哈希与报告标识相对同样 Go 字段直接构造的结果保持原有值。
310		direct := Artifact{Name: " 金库 Vault ", ABI: abi, Bytecode: bytecode, Source: source}
311		if ArtifactHash(artifact) != ArtifactHash(direct) {
312			t.Fatal("the parsed artifact must hash exactly like the directly constructed one")
313		}
314		report := strictParsedReport(t, in)
315		if report.Artifact.Hash != ArtifactHash(direct) {
316			t.Fatalf("report must bind the original hash: %q", report.Artifact.Hash)
317		}
318	}
319	
320	// --- 缺失或 null 的 artifact 对象沿用既有“artifact name is required”判断 ---
321	
322	func TestParseAuditMissingArtifactObjectKeepsBusinessError(t *testing.T) {
323		for _, in := range []string{
324			`{"rules":[]}`,
325			`{"artifact":null,"rules":[]}`,
326		} {
327			a, rules, inv, checks, err := ParseAuditInput([]byte(in))
328			if err != nil {
329				t.Fatalf("a missing/null artifact object parses with defaults as before: %v", err)
330			}
331			if _, err := BuildReport(a, rules, inv, checks); err == nil ||
332				!strings.Contains(err.Error(), "artifact name is required") {
333				t.Fatalf("missing artifact must keep the existing required-name error: %v", err)
334			}
335		}
336	}
