42	// runAudit parses an audit submission, builds the report and saves it.
43	func runAudit(args []string) {
44		fs := flag.NewFlagSet("audit", flag.ContinueOnError)
45		fs.SetOutput(os.Stderr)
46		inputPath := fs.String("input", "", "path to the audit input JSON file")
47		store := fs.String("store", "", "report store directory")
48		if err := fs.Parse(args); err != nil {
49			os.Exit(2)
50		}
51		if *inputPath == "" || *store == "" {
52			fmt.Fprintln(os.Stderr, "usage: contractsentinel audit --input <file> --store <dir>")
53			os.Exit(2)
54		}
55		data, err := os.ReadFile(*inputPath)
56		if err != nil {
57			fail("audit", err)
58		}
59		artifact, rules, invariants, checks, err := contractsentinel.ParseAuditInput(data)
60		if err != nil {
61			fail("audit", err)
62		}
63		report, err := contractsentinel.BuildReport(artifact, rules, invariants, checks)
64		if err != nil {
65			fail("audit", err)
66		}
67		if err := contractsentinel.SaveReport(*store, report); err != nil {
68			fail("audit", err)
69		}
70		printReport("audit", report)
71	}
72	
73	// runReport reads a saved report by id and prints it.
74	func runReport(args []string) {
75		fs := flag.NewFlagSet("report", flag.ContinueOnError)
76		fs.SetOutput(os.Stderr)
77		store := fs.String("store", "", "report store directory")
78		id := fs.String("id", "", "report id")
79		if err := fs.Parse(args); err != nil {
80			os.Exit(2)
81		}
82		if *store == "" || *id == "" {
83			fmt.Fprintln(os.Stderr, "usage: contractsentinel report --store <dir> --id <id>")
84			os.Exit(2)
85		}
86		report, err := contractsentinel.LoadReport(*store, *id)
87		if err != nil {
88			fail("report", err)
89		}
