93	// runDiff compares two stored reports and prints the diff JSON.
94	func runDiff(args []string) {
95		fs := flag.NewFlagSet("diff", flag.ContinueOnError)
96		fs.SetOutput(os.Stderr)
97		store := fs.String("store", "", "report store directory")
98		before := fs.String("before", "", "baseline report id")
99		after := fs.String("after", "", "new report id")
100		if err := fs.Parse(args); err != nil {
101			os.Exit(2)
