133	func runDemo() {
134		artifact := contractsentinel.Artifact{Name: "Vault", ABI: "[{\"name\":\"withdraw\"}]", Bytecode: "0x6080", Source: "Vault.sol"}
135		rules := []contractsentinel.Rule{
