	explicitFalse := requiresABIDoc(requiresABIRule(`"requiresABI":false`), "")
	if _, _, _, _, err := ParseAuditInput([]byte(explicitFalse)); err != nil {
		t.Fatalf("explicit false without an ABI must stay legal: %v", err)
	}

